import React, { useState } from 'react';

function SchedulePage() {
  const today = new Date();
  
  const dates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(today.getDate() + i);
    const dayNames = ['일', '월', '화', '수', '목', '금', '토'];
    return {
      dateObj: d,
      dayLabel: i === 0 ? '오늘' : dayNames[d.getDay()],
      dateNum: d.getDate(),
      fullDateString: `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, '0')}.${String(d.getDate().padStart ? d.getDate() : String(d.getDate())).padStart(2, '0')}`
    };
  });

  const [selectedDateIndex, setSelectedDateIndex] = useState(0);
  const selectedDate = dates[selectedDateIndex];

  const formattedSelectedDate = `${selectedDate.dateObj.getFullYear()}.${String(selectedDate.dateObj.getMonth() + 1).padStart(2, '0')}.${String(selectedDate.dateObj.getDate()).padStart(2, '0')}`;

  const scheduleDataMap = {
    0: [
      { id: 1, title: "오디세이", type: "돌비시네마 (1관)", rating: "전체관람가", runtime: "142분", times: [{ t: "10:00", seat: "120석 (조조)" }, { t: "13:10", seat: "85석 (일반)" }, { t: "16:40", seat: "12석 (일반)" }, { t: "20:00", seat: "0석 (마감)" }] },
      { id: 2, title: "싱 어 게 인", type: "일반상영관 2관", rating: "12세이상관람가", runtime: "110분", times: [{ t: "11:20", seat: "90석 (조조)" }, { t: "14:30", seat: "140석 (일반)" }, { t: "17:50", seat: "60석 (일반)" }] }
    ],
    1: [
      { id: 1, title: "스파이더맨: 브랜드 뉴 데이", type: "돌비시네마 (1관)", rating: "12세이상관람가", runtime: "135분", times: [{ t: "09:30", seat: "150석 (조조)" }, { t: "12:40", seat: "110석 (일반)" }, { t: "15:50", seat: "45석 (일반)" }, { t: "19:10", seat: "10석 (마감)" }] },
      { id: 3, title: "인턴", type: "일반상영관 3관", rating: "12세이상관람가", runtime: "121분", times: [{ t: "10:30", seat: "100석 (조조)" }, { t: "13:50", seat: "80석 (일반)" }, { t: "17:10", seat: "30석 (일반)" }] }
    ],
    2: [
      { id: 4, title: "옵세션", type: "돌비시네마 (1관)", rating: "15세이상관람가", runtime: "118분", times: [{ t: "11:00", seat: "130석 (조조)" }, { t: "14:20", seat: "95석 (일반)" }, { t: "18:00", seat: "5석 (마감)" }] }
    ],
    3: [
      { id: 5, title: "타짜: 반전의 노래", type: "일반상영관 1관", rating: "청소년관람불가", runtime: "139분", times: [{ t: "13:00", seat: "110석 (일반)" }, { t: "16:30", seat: "60석 (일반)" }, { t: "20:10", seat: "20석 (일반)" }] }
    ],
    4: [
      { id: 6, title: "경주기행", type: "일반상영관 2관", rating: "12세이상관람가", runtime: "115분", times: [{ t: "10:15", seat: "140석 (조조)" }, { t: "13:40", seat: "90석 (일반)" }, { t: "17:00", seat: "40석 (일반)" }] }
    ],
    5: [
      { id: 7, title: "비광", type: "돌비시네마 (1관)", rating: "15세이상관람가", runtime: "108분", times: [{ t: "12:00", seat: "125석 (일반)" }, { t: "15:20", seat: "80석 (일반)" }, { t: "18:40", seat: "15석 (마감)" }] }
    ],
    6: [
      { id: 8, title: "부활남", type: "일반상영관 3관", rating: "15세이상관람가", runtime: "125분", times: [{ t: "11:10", seat: "100석 (조조)" }, { t: "14:50", seat: "75석 (일반)" }, { t: "19:00", seat: "50석 (일반)" }] }
    ]
  };

  const currentMovies = scheduleDataMap[selectedDateIndex] || [];

  return (
    <div className="w-full min-h-screen bg-white text-zinc-800 font-sans pb-24" style={{ fontFamily: 'Pretendard, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif' }}>
      
      {/* 상단 타이틀 영역 */}
      <div className="max-w-7xl mx-auto px-6 pt-10">
        <h2 className="text-2xl font-black tracking-tight text-zinc-900">상영시간표</h2>
        <p className="text-xs text-zinc-500 mt-1">메가박스 전국의 상영시간표를 한눈에 확인하세요.</p>
      </div>

      {/* 날짜 선택 바 영역 */}
      <div className="max-w-7xl mx-auto px-6 mt-6">
        <div className="bg-white border border-zinc-200 rounded-2xl p-4 shadow-sm flex flex-col md:flex-row items-center justify-between gap-4">
          
          <div className="flex items-center gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0">
            {dates.map((item, idx) => {
              const isSelected = selectedDateIndex === idx;
              return (
                <button
                  key={idx}
                  onClick={() => setSelectedDateIndex(idx)}
                  className={`flex flex-col items-center justify-center min-w-[56px] h-16 rounded-xl transition-all font-bold ${
                    isSelected 
                      ? 'bg-[#503396] text-white shadow-md scale-105' 
                      : 'bg-zinc-100 text-zinc-600 hover:bg-zinc-200'
                  }`}
                >
                  <span className="text-[11px] font-semibold">{item.dayLabel}</span>
                  <span className="text-base font-black mt-0.5">{item.dateNum}</span>
                </button>
              );
            })}
          </div>

          <div className="text-sm font-black text-zinc-700 bg-zinc-50 px-4 py-2 rounded-xl border border-zinc-200 whitespace-nowrap">
            {formattedSelectedDate} 선택됨
          </div>

        </div>
      </div>

      {/* 상영 스케줄 목록 영역 */}
      <div className="max-w-7xl mx-auto px-6 mt-8 space-y-6">
        {currentMovies.length === 0 ? (
          <div className="text-center py-20 bg-zinc-50 rounded-2xl border border-zinc-200 text-zinc-400 text-sm font-bold">
            해당 날짜에 등록된 상영 스케줄이 없습니다.
          </div>
        ) : (
          currentMovies.map((movie) => (
            <div key={movie.id} className="bg-white border border-zinc-200 rounded-2xl p-6 shadow-sm space-y-4">
              
              {/* 상영관 및 관람등급 정보 */}
              <div className="flex items-center justify-between border-b border-zinc-100 pb-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold px-2 py-0.5 rounded bg-purple-50 text-[#503396] border border-purple-200">
                    {movie.type}
                  </span>
                </div>
                <span className="text-xs font-medium text-zinc-500">
                  {movie.rating} &bull; {movie.runtime}
                </span>
              </div>

              {/* 영화 제목 및 시간표 리스트 */}
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pt-2">
                <h3 className="text-lg font-black text-zinc-900 tracking-tight">
                  {movie.title}
                </h3>

                <div className="flex flex-wrap gap-3">
                  {movie.times.map((timeSlot, tIdx) => (
                    <div 
                      key={tIdx} 
                      className="flex flex-col items-center justify-center border border-zinc-300 hover:border-[#503396] rounded-xl px-4 py-2 bg-white cursor-pointer transition shadow-sm group"
                    >
                      <span className="text-sm font-black text-zinc-900 group-hover:text-[#503396]">{timeSlot.t}</span>
                      <span className="text-[10px] font-semibold text-zinc-400 mt-0.5">{timeSlot.seat}</span>
                    </div>
                  ))}
                </div>
              </div>

            </div>
          ))
        )}
      </div>

    </div>
  );
}

export default SchedulePage;
